    function openPublishModal() {
      openModal('modal-publish-signup');
      closeModal('modal-detail-c3');
    }

    function confirmPublishSignup() {
      // 模擬：發布成功後，切換狀態為「報名中」
      closeModal('modal-publish-signup');

      const ptCount = document.getElementById('publish-pt-count').value;
      const otCount = document.getElementById('publish-ot-count').value;
      const stCount = document.getElementById('publish-st-count').value;
      const deadline = document.getElementById('publish-deadline').value;

      // 更新陳志明的卡片 UI 為報名中
      updateC3UI('signup', { pt: ptCount, ot: otCount, st: stCount, deadline: deadline });
      alert('已成功發布報名！系統將通知相關治療師。');
    }

    function simulateDeadline(result) {
      if (result === 'zero') {
        updateC3UI('unestablished_zero');
        alert('報名人數為 0，此班表未成立。');
      } else if (result === 'not_enough') {
        openModal('modal-waitlist-deadline');
      } else if (result === 'exceed') {
        alert('報名人數超額，系統已自動抽籤，並送交主管審核！');
        updateC3UI('pending_approval');
        openModal('modal-approval-signup');
      }
    }

    function confirmWaitlistDeadline() {
      closeModal('modal-waitlist-deadline');
      updateC3UI('waitlist');
      alert('已開放補位，系統等待補位截止。');
    }

    function simulateWaitlist() {
      // 模擬補位到期未滿員 -> 未成立
      updateC3UI('unestablished_waitlist');
      alert('補位期限已到，仍未滿員，此班表未成立。已錄取治療師的排班將被取消。');
    }

    function resetPublishFlow() {
      updateC3UI('initial');
    }

    function rejectApprovalSignup() {
      closeModal('modal-approval-signup');
      openModal('modal-manual-adjust');
    }

    function approveApprovalSignup() {
      closeModal('modal-approval-signup');
      updateC3UI('established');
      alert('主管已同意名單，班表已正式成立！');
    }

    function confirmManualAdjust() {
      closeModal('modal-manual-adjust');
      updateC3UI('established_manual');
      alert('手動調整完成，班表已正式成立！');
    }

    function updateC3UI(state, data) {
      const cards = document.querySelectorAll('.case-card');
      let targetCard = null;
      cards.forEach(card => {
        const nameEl = card.querySelector('.case-name');
        if (nameEl && nameEl.textContent.trim() === '陳志明') {
          targetCard = card;
        }
      });

      if (!targetCard) return;

      const cardBadges = targetCard.querySelector('.case-card-badges');
      const simTools = document.getElementById('simulation-tools');
      const btnSimWaitlist = document.getElementById('btn-sim-waitlist');

      simTools.style.display = 'block';

      if (state === 'initial') {
        cardBadges.innerHTML = `<span class="badge badge-gray">可發佈</span><span style="font-size:11px;color:var(--gray-400)">尚未發布報名</span>`;
        document.getElementById('c3-publish-note').textContent = '此個案尚未發布報名，請通知復健主管發布或前往「發布報名」頁面。';
        document.getElementById('c3-publish-note').className = 'info-note amber';
        document.getElementById('modal-footer-c3').innerHTML = `
          <button class="btn btn-secondary" onclick="closeModal('modal-detail-c3')">關閉</button>
          <button id="btn-publish-c3" class="btn btn-primary" onclick="openPublishModal()">📢 發布報名</button>
        `;
        btnSimWaitlist.style.display = 'none';
      } else if (state === 'signup') {
        cardBadges.innerHTML = `<span class="badge badge-amber" style="background:#fef3c7;color:#d97706;border:1px solid #fcd34d;">報名中</span><span style="font-size:11px;color:var(--gray-400)">PT ${data.pt} / OT ${data.ot} / ST ${data.st}</span>`;
        document.getElementById('c3-publish-note').textContent = '此個案正在報名中，等待治療師報名。';
        document.getElementById('c3-publish-note').className = 'info-note blue';
        document.getElementById('modal-footer-c3').innerHTML = `
          <button class="btn btn-secondary" onclick="closeModal('modal-detail-c3')">關閉</button>
        `;
      } else if (state === 'unestablished_zero' || state === 'unestablished_waitlist') {
        cardBadges.innerHTML = `<span class="badge" style="background:#fee2e2;color:#ef4444;border:1px solid #fca5a5;">未成立</span><span style="font-size:11px;color:var(--gray-400)">因人數不足取消</span>`;
        document.getElementById('c3-publish-note').textContent = '此個案報名未成立，已取消。';
        document.getElementById('c3-publish-note').className = 'info-note red';
        btnSimWaitlist.style.display = 'none';
      } else if (state === 'waitlist') {
        cardBadges.innerHTML = `<span class="badge" style="background:#dbeafe;color:#3b82f6;border:1px solid #bfdbfe;">開放補位</span><span style="font-size:11px;color:var(--gray-400)">等待補位中</span>`;
        document.getElementById('c3-publish-note').textContent = '目前為開放補位狀態。';
        document.getElementById('c3-publish-note').className = 'info-note amber';
        btnSimWaitlist.style.display = 'inline-block';
      } else if (state === 'pending_approval') {
        cardBadges.innerHTML = `<span class="badge" style="background:#fef3c7;color:#d97706;border:1px solid #fcd34d;">待主管確認</span><span style="font-size:11px;color:var(--gray-400)">需審核名單</span>`;
        document.getElementById('c3-publish-note').textContent = '名單已產出，待主管確認中。';
        document.getElementById('c3-publish-note').className = 'info-note blue';
        btnSimWaitlist.style.display = 'none';
      } else if (state === 'established' || state === 'established_manual') {
        cardBadges.innerHTML = `<span class="badge badge-green">已成立</span><span style="font-size:11px;color:var(--gray-400)">執行中</span>`;
        document.getElementById('c3-publish-note').textContent = '班表已正式成立，準備執行。';
        document.getElementById('c3-publish-note').className = 'info-note green';
        btnSimWaitlist.style.display = 'none';
      }
    }
  </script>
</body>
</html>

