function switchRole(role) {
  currentRole = role;
  const btnAddCaseWrap = document.getElementById('btn-add-case-wrap');
  const btnPublishRecordWrap = document.getElementById('btn-publish-record-wrap');
  const btnBonusWrap = document.getElementById('btn-bonus-wrap');

  ['case', 'manager', 'therapist'].forEach(r => {
    const btn = document.getElementById('rbtn-' + r);
    if (btn) btn.classList.toggle('active', r === role);
  });

  // 隱藏其他全域畫面
  const views = ['view-main', 'view-bonus'];
  views.forEach(v => {
    const el = document.getElementById(v);
    if (el) el.classList.add('hidden');
  });

  if (role === 'case') {
    document.getElementById('ua').className = 'user-avatar av-case';
    document.getElementById('ua').textContent = '林';
    document.getElementById('uname').textContent = '林美惠';
    document.getElementById('urole').textContent = '個案管理師';

    if (btnAddCaseWrap) btnAddCaseWrap.classList.remove('hidden');
    if (btnPublishRecordWrap) btnPublishRecordWrap.classList.remove('hidden');
    if (btnBonusWrap) btnBonusWrap.classList.remove('hidden');
  } else if (role === 'manager') {
    document.getElementById('ua').className = 'user-avatar av-manager';
    document.getElementById('ua').textContent = '王';
    document.getElementById('uname').textContent = '王復健主管';
    document.getElementById('urole').textContent = '復健主管';

    if (btnAddCaseWrap) btnAddCaseWrap.classList.add('hidden');
    if (btnPublishRecordWrap) btnPublishRecordWrap.classList.remove('hidden');
    if (btnBonusWrap) btnBonusWrap.classList.remove('hidden');
  } else {
    document.getElementById('ua').className = 'user-avatar av-therapist';
    document.getElementById('ua').textContent = '黃';
    document.getElementById('uname').textContent = '黃志豪';
    document.getElementById('urole').textContent = '物理治療師（PT）';

    if (btnAddCaseWrap) btnAddCaseWrap.classList.add('hidden');
    if (btnPublishRecordWrap) btnPublishRecordWrap.classList.add('hidden');
    if (btnBonusWrap) btnBonusWrap.classList.remove('hidden');
  }

  document.getElementById('view-main').classList.remove('hidden');
  prevView = 'view-main';
}

function switchToBonus() {
  ['view-main'].forEach(v => {
    const el = document.getElementById(v);
    if (el) el.classList.add('hidden');
  });
  document.getElementById('view-bonus').classList.remove('hidden');
}
function switchBackFromBonus() {
  document.getElementById('view-bonus').classList.add('hidden');
  document.getElementById(prevView).classList.remove('hidden');
}

function toggleCase(id) {
  const el = document.getElementById('modal-detail-' + id);
  if (el) {
    openModal('modal-detail-' + id);
  } else {
    // Dynamic case detail alert
    let caseName = '未知個案';
    const cards = document.querySelectorAll('#case-list-all .case-card');
    cards.forEach(card => {
      const header = card.querySelector('.case-card-header');
      if (header) {
        const onclickAttr = header.getAttribute('onclick');
        if (onclickAttr && onclickAttr.includes(id)) {
          caseName = card.querySelector('.case-name').textContent;
        }
      }
    });
    alert('查看個案：' + caseName + '，此個案為動態新增案例，目前暫不提供完整歷史詳情面版。');
  }
}

function switchCaseTab(el, tab) {
  document.querySelectorAll('#view-main .tabs .tab').forEach(t => t.classList.remove('active'));
  el.classList.add('active');

  const cards = document.querySelectorAll('#case-list-all .case-card');
  cards.forEach(card => {
    const status = card.getAttribute('data-status') || '';
    if (tab === 'all') {
      card.classList.remove('hidden');
    } else if (tab === 'active' && status === 'active') {
      card.classList.remove('hidden');
    } else if (tab === 'publish' && status === 'publish') {
      card.classList.remove('hidden');
    } else if (tab === 'open' && status === 'open') {
      card.classList.remove('hidden');
    } else if (tab === 'billing' && status === 'billing') {
      card.classList.remove('hidden');
    } else if (tab === 'ending' && status === 'ending') {
      card.classList.remove('hidden');
    } else {
      card.classList.add('hidden');
    }
  });
}

