const fs = require('fs');
const files = [
  'c:/Users/pantx/Desktop/codeX_test/src/pages/legacy-html/home-care-scheduling.html',
  'c:/Users/pantx/Desktop/codeX_test/src/pages/legacy-html/rehab-scheduling.html'
];
const mapping = {
  '骨科（膈關節）': '脆弱性骨折',
  '脊髓損傷（C4-C5）': '創傷性神經損傷',
  '脊髓損傷': '創傷性神經損傷',
  '骨科（髖關節置換後）': '脆弱性骨折',
  '骨科（髖關節）': '脆弱性骨折',
  'CVA（腦中風）': '腦中風(CVA)',
  '帕金森氏症': '衰弱高齡',
  '骨科（膝關節置換後）': '脆弱性骨折',
  '骨科（膝關節）': '脆弱性骨折',
  'COPD（慢性阻塞性肺病）': '衰弱高齡',
  'COPD（慢性阻塞性胺病）': '衰弱高齡',
  '骨科（右側全膝關節置換術後）': '脆弱性骨折',
  'CVA（腦梗塞・右側偏癱）': '腦中風(CVA)',
  '骨科': '脆弱性骨折'
};
files.forEach(file => {
  let content = fs.readFileSync(file, 'utf8');
  for (const [key, value] of Object.entries(mapping)) {
    // Only replace within elements that might contain disease names.
    // However, since these disease names are very specific, global replace is mostly safe.
    // Let's use a regex to ensure we catch them all.
    const regex = new RegExp(key.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&'), 'g');
    content = content.replace(regex, value);
  }
  fs.writeFileSync(file, content);
});
console.log('Replacement complete.');

const fs = require('fs');

// Fix home-care-scheduling.html
let hcFile = 'c:/Users/pantx/Desktop/codeX_test/src/pages/legacy-html/home-care-scheduling.html';
