hc = hc.replace(/<div class="summary-box" style="margin-bottom:12px">COPD\s*於本院住院復健完成，目前進入居家階段。呼吸功能案引，需加強呼吸肌訓練、步行耐力及排痰技巧指導。注意：若血氧濓度下降 90% 即停止並提醒。01 。<\/div>/g, '<div class="summary-box" style="margin-bottom:12px">腦中風(CVA)於本院住院復健完成，目前進入居家階段。需加強患側肢體肌力、關節活動度訓練及防跌倒指導。</div>');

hc = hc.replace(/<div class="summary-box" style="margin-bottom:12px">PT：每週 3 次，每次 50 分鐘。著重呼吸肌訓練、步行耐力提升及排痰技巧指導。<br>ST：每週 1 次，每次 40\s*分鐘。吠嚥功能訓練、溝通能力評估。<\/div>/g, '<div class="summary-box" style="margin-bottom:12px">PT：每週 3 次，每次 50 分鐘。著重肢體復健、步態訓練、轉位指導。<br>ST：每週 1 次，每次 40 分鐘。吞嚥功能訓練、溝通能力評估。</div>');


// Fix other summaries in home-care-scheduling.html
hc = hc.replace(/<div class="summary-box" style="margin-bottom:12px">COPD 慢性阻塞性肺病，常有呼吸急促，體力下降。<\/div>/g, '<div class="summary-box" style="margin-bottom:12px\">衰弱高齡，常有呼吸急促，體力下降。</div>');

hc = hc.replace(/<div class="summary-box" style="margin-bottom:12px">CVA 腦梗塞後右側偏癱，需復健治療。右側上下肢功能記錄區分\s*1-2\/5，語言功能輕度障礌。復健目標：步態訓練、功能性体能訓練及語言訓練。<\/div>/g, '<div class="summary-box" style="margin-bottom:12px">腦中風(CVA)右側偏癱，需復健治療。右側上下肢功能記錄區分 1-2/5，語言功能輕度障礙。復健目標：步態訓練、功能性體能訓練及語言訓練。</div>');

hc = hc.replace(/<div class="summary-box" style="margin-bottom:12px">COPD 中度，倒年 FEV1\s*52%。走路耗辺晋額不良，伴輕度咯嗽。需升強呼吸功能、步行耐力及排痰技巧，配合家庭水療評估。<\/div>/g, '<div class="summary-box" style="margin-bottom:12px">衰弱高齡，體力不佳，走路容易喘，伴輕度咳嗽。需加強心肺功能、步行耐力。</div>');


fs.writeFileSync(hcFile, hc);


// Fix rehab-scheduling.html
let rsFile = 'c:/Users/pantx/Desktop/codeX_test/src/pages/legacy-html/rehab-scheduling.html';
let rs = fs.readFileSync(rsFile, 'utf8');

rs = rs.replace(/李文雄（COPD・院內）/g, '李文雄（腦中風(CVA)・院內）');
